async function sendAISummaryToTeams(report, options = {}, logs = false) {
  if (options.token) {
    process.env.TEAMS_WEBHOOK_URL = options.token;
  }
  for (const test of report.results.tests) {
    if (test.status === "failed") {
      const message = formatAiSummaryForTest(
        test,
        report.results.environment || {}
      );
      if (message) {
        await sendTeamsMessage(message);
        logs && console.log(`AI summary message sent to Teams for ${test.name}.`);
      }
    }
  }
}

// src/integrations/teams.ts
async function handleTeamsIntegration(config, report) {
  const integrationReport = report;
  startGroup("\u{1F4AC} Processing Teams Integration");
  info(`Processing Teams integration for action: ${config.action}`);
  switch (config.action) {
    case "results": {
      await sendTestResultsToTeams(integrationReport, config, false);
      info("sent results to Teams");
      break;
    }
    case "flaky": {
      await sendFlakyResultsToTeams(integrationReport, config, false);
      info("sent flaky results to Teams");
      break;
    }
    case "ai": {
      await sendAISummaryToTeams(integrationReport, config, false);
      info("sent AI summary to Teams");
      break;
    }
    default:
      warning(
        `Unknown action type, valid actions are: results, flaky, ai`
      );
      warning(
        `Please check your integrations-config input for any typos or missing integrations.`
      );
      warning(`Moving on without teams integration...`);
  }
  info(`Teams integration processed for action: ${config.action}`);
  endGroup();
}

