async function generateAISummary(config, report) {
  const integrationReport = report;
  if (!config || Object.keys(config).length === 0) {
    warning("AI config required for ai-summary-report but not provided");
    return;
  }
  const aiConfig = config;
  if (!aiConfig.provider) {
    warning(
      "AI config provided but no provider specified for ai-summary-report"
    );
    return;
  }
  startGroup("\u{1F916} Generating AI Summary CTRFReport");
  info(`Generating AI Summary for provider: ${aiConfig.provider}`);
  const { provider: _provider, ...rest } = aiConfig;
  const options = {
    log: false,
    consolidate: true,
    ...rest
  };
  try {
    const aiSummaryData = await generateJsonSummary(
      integrationReport,
      aiConfig.provider,
      options
    );
    if (aiSummaryData) {
      report.results.extra = report.extra || {};
      report.results.extra.aiSummary = aiSummaryData;
      info("AI Summary CTRFReport generated successfully");
    } else {
      warning("Failed to generate AI summary");
    }
  } catch (error2) {
    error(`Error generating AI summary report: ${error2}`);
  }
  endGroup();
}

// src/integrations/handler.ts
async function processIntegration(name, cfg, report) {
  debug(`Processing ${name} integration`);
  switch (name) {
    case "slack":
      await handleSlackIntegration(cfg, report);
      break;
    case "teams":
      await handleTeamsIntegration(cfg, report);
      break;
    case "ai":
      await handleAIIntegration(cfg, report);
      break;
    case "junit-to-ctrf":
      break;
    default:
      warning(`Unknown integration: ${name}`);
      warning(
        `Please check your integrations-config.json file for any typos or missing integrations.`
      );
      warning(`Available integrations are: slack, teams, ai`);
      warning(`Moving on without ${name} integration...`);
  }
}
async function processIntegrations(config, report) {
  if (!config) return;
  try {
    const enabledIntegrations = getEnabledIntegrations(config);
    const sortedIntegrations = sortIntegrations(enabledIntegrations);
    for (const [name, cfg] of sortedIntegrations) {
      await processIntegration(name, cfg, report);
    }
  } catch (error2) {
    error(`Error processing integrations: ${error2}`);
  }
}
function sortIntegrations(entries) {
  return entries.sort(([nameA], [nameB]) => {
    if (nameA === "ai") return -1;
    if (nameB === "ai") return 1;
    return 0;
  });
}
function getEnabledIntegrations(config) {
  if (!config) return [];
  const entries = Object.entries(config);
  return entries.filter(([, integration]) => integration?.enabled);
}

// src/core/action-handler.ts
async function runAction() {
  try {
    const inputs = getInputs();
    const githubContext = getAllGitHubContext();
    const report = await prepareReport(inputs, githubContext);
    await handleStandaloneAIIntegration(inputs.ai, report);
    await processIntegrations(inputs.integrationsConfig, report);
    if (inputs.aiSummaryReport) {
      await generateAISummary(inputs.ai, report);
    }
    await handleViewsAndComments(inputs, report);
    handleAnnotations(inputs, report);
    if (inputs.exitOnEmpty) {
      exitActionOnEmpty(report);
    }
    if (inputs.exitOnFail) {
      exitActionOnFail(report);
    }
    startGroup(`\u{1F3C1} Report completed`);
    endGroup();
    startGroup(
      `\u2B50 CTRF is open source and free to use, you can show your support by starring the repo at https://github.com/ctrf-io/github-test-reporter`
    );
    endGroup();
  } catch (error2) {
    handleError(error2);
  }
}

// src/index.ts
async function run() {
  await runAction();
}
run().then(() => {
}).catch(() => {
});
